sksl:
uniform shader image;
uniform float2 size;
uniform float phase;
uniform float amount;
uniform float scale;
layout(color) uniform half4 tint;
float hash(float2 p){return fract(sin(dot(p,float2(127.1,311.7)))*43758.5453);}half4 effectMain(float2 coord){half4 c=image.eval(coord);float2 cell=floor(coord/scale);float n=hash(cell);float y=fract(coord.y/size.y+phase*(0.5+n));float x=fract(coord.x/size.x+n);float d=abs(fract(x*17.0)-0.5);float m=(1.0-smoothstep(0.03,0.08,d))*step(1.0-amount,n);return half4(clamp(c.rgb+tint.rgb*half(m*0.8)*c.a,half3(0),half3(1)),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
